const PE_area=(f,t0,t1,x0,x1,yc,k,col,fill,w=3,n=360)=>{const p=PE_pts(f,t0,t1,x0,x1,yc,k,n);return `<path d="M${x0} ${yc}${p.map(q=>'L'+q[0].toFixed(1)+' '+q[1].toFixed(1)).join('')}L${x1} ${yc}Z" fill="${fill}" stroke="${col}" stroke-width="${w}" stroke-linejoin="round"/>`};
/* the waves of this lesson: supply sine; load voltage of a controller conducting from a to b in each half (degrees) */
const PE_sin=t=>Math.sin(PE_rad(t));
const PE_on=(t,a,b)=>{const m=((t%360)+360)%360;return (m>=a&&m<=b)||(m>=180+a&&m<=180+b)||(m+360>=180+a&&m+360<=180+b)};
