/* RL load current, α = 60°, φ = 45° (tan φ = 1): i/(Vm/Z) = sin(θ − φ) − sin(α − φ)·exp(−(θ − α)), zero again at β = 224.2° */
const PE_iRL=t=>{const m=((t%360)+360)%360,h=(x)=>(x>=60&&x<=224.2)?Math.sin(PE_rad(x-45))-Math.sin(PE_rad(15))*Math.exp(-PE_rad(x-60)):0;return m>=180?-h(m-180):(m<=44.2?-h(m+180):h(m))};
