const PE_capV=(x,y1,y2,col=PE_INK,w=3)=>{const m=(y1+y2)/2;return PE_L(x,y1,x,m-7,col,w)+PE_L(x,m+7,x,y2,col,w)+PE_L(x-20,m-7,x+20,m-7,col,w+2)+PE_L(x-20,m+7,x+20,m+7,col,w+2)};
const PE_ac=(cx,cy,r=26,col=ORG)=>`<circle cx="${cx}" cy="${cy}" r="${r}" fill="#FFFFFF" stroke="${col}" stroke-width="3"/>`+PE_curve(t=>PE_sin(t),0,360,cx-r*.6,cx+r*.6,cy,r*.35,col,3,'',40);
