const PE_pair=(x1,x2,y,col=PE_INK,lab=1)=>{const m=(x1+x2)/2,d=26;return PE_L(x1,y,x1+14,y,col,3)+PE_L(x2-14,y,x2,y,col,3)+PE_L(x1+14,y-d,x1+14,y+d,col,3)+PE_L(x2-14,y-d,x2-14,y+d,col,3)+PE_L(x1+14,y-d,x2-14,y-d,col,3)+PE_L(x1+14,y+d,x2-14,y+d,col,3)+PE_tri(m,y-d,12,1,col)+PE_tri(m,y+d,12,-1,col)+PE_L(m+12,y-d+10,m+24,y-d+24,col,2.5)+PE_L(m-12,y+d-10,m-24,y+d-24,col,2.5)+(lab?PE_T(m,y-d-16,'T1',{fs:22,fw:800,a:'middle',fill:col})+PE_T(m,y+d+34,'T2',{fs:22,fw:800,a:'middle',fill:col}):'')};
