 ICON.peRc3=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${PE_L(40,30,380,30,PE_INK,3)}${PE_L(40,310,380,310,PE_INK,3)}${PE_L(40,30,40,140,PE_INK,3)}${PE_L(40,200,40,310,PE_INK,3)}${PE_ac(40,170,30)}${PE_lamp(130,30,1,20)}${PE_triac(230,30,310,PE_INK,0,1)}${PE_resV(380,30,180,PE_INK,3)}${PE_L(380,180,380,206,PE_INK,3)}${PE_capV(380,206,310,PE_INK,3)}${PE_dot(380,206,PE_INK,5)}${PE_diac(282,380,206,GRN)}${PE_T(400,112,'R',{fs:28,fw:800})}${PE_T(410,268,'C',{fs:28,fw:800})}${PE_T(318,250,'DIAC',{fs:24,fw:800,a:'middle',fill:GRN})}${PE_T(150,186,'TRIAC',{fs:24,fw:800,a:'middle'})}</g>`;
